module jobs

enum Status { New, Queued, Running, Cancelling, Succeeded, Failed, Cancelled }

machine Job {
  state {
    status   : Status = New
    tries    : 0..3   = 0
    maxTries : 0..3   = 0
  }
  terminal status in { Succeeded, Failed, Cancelled }

  action Submit(max: int check 0..4)
  action Claim()
  action Succeed()
  action Fail()
  action Cancel()

  on Submit(max) {
    require status is New else reject "job-exists"
    require max >= 1 and max <= 3 else reject "max-tries-out-of-range"
    status' = Queued
    maxTries' = max
  }
